function updateKrea2TurboUI(){const mode=$("krea2-turbo-mode"),steps=$("krea2-steps"),model=$("krea2-model"),note=$("krea2-turbo-note");if(!mode||!steps)return;const turboModel=!!(model&&model.value),profile=turboModel?"gguf":"sickrealism",current=Number(mode.value)||0;if(mode.dataset.profile!==profile){mode.innerHTML=turboModel?'<option value="0">Uit · standaard</option><option value="4">4 stappen · Turbo (gebalanceerd)</option><option value="2">2 stappen · Turbo preview</option>':'<option value="0">Uit · standaard</option><option value="3">3 stappen · alternatief</option><option value="2">2 stappen · preview</option>';mode.value=turboModel?((current===4||current===2)?String(current):"0"):(current===2||current===3?String(current):"0");mode.dataset.profile=profile;}mode.disabled=false;const selectedTurbo=Number(mode.value)||0;if(selectedTurbo){if(!steps.dataset.standardBeforeTurbo)steps.dataset.standardBeforeTurbo=steps.value;steps.value=String(selectedTurbo);steps.disabled=true;}else{steps.disabled=false;if(steps.dataset.standardBeforeTurbo){steps.value=steps.dataset.standardBeforeTurbo;delete steps.dataset.standardBeforeTurbo;}}if(note){const n=Number(mode.value);note.textContent=turboModel?(n===4?"Krea2 Turbo Q3 + 4-step LoRA · PS5-meting 6 nov 2026: 768×768 detailbeeld 85 s koud en 55 s warm; 512×512 65 s koud. Eerdere warmmetingen vóór de GTT-uitbreiding: 30,2–36,2 s op 512×512 en 23,5–24,9 s op 384×384. De nieuwe 768-test bleef stabiel met circa 2 GiB RAM beschikbaar.":n===2?"Krea2 Turbo Q3 + 2-step LoRA · PS5-meting: circa 60,0 s op 512×512, trager dan warm 4-step (30,2–36,2 s); kies 2-step alleen als je de andere beeldstijl verkiest.":"Krea2 Turbo Q3 · PS5-meting 5 nov 2026: standaard 8 stappen 54,6 s warm op 512×512; 4-step Turbo-LoRA 30,2–36,2 s warm (2 runs); 2-step Turbo 60,0 s. Eén standaard- en één 2-step-meting."):n===3?"Turbo 3-step LoRA · 54,5 s gemeten op 512×512 · ongeveer even snel als standaard 4 stappen, met een andere textuur. Experimenteel op Sickrealism.":n===2?"Turbo 2-step LoRA-preview · 36,3 s gemeten op 512×512 · coherenter dan standaard 2 stappen, maar alleen bedoeld voor snelle previews.":"Standaard Sickrealism-sampling. 8 stappen: 106,6 s warm; 4 stappen: 54,5 s; 2 stappen: 28,9 s maar zichtbaar zachter.";}}
