async function startKrea2Generation(originalPrompt,finalPrompt,meta,mode,edited=false,keepPromptVisible=false){
 const prompt=String(finalPrompt||"").trim();if(!prompt||prompt.length>6000)return toast("Prompt moet 1 tot 6000 tekens bevatten.");
 const promptSource=(meta?.provider||"original")==="original"?"original":"optimized",warning=String(meta?.warning||"").slice(0,360);
 if(!keepPromptVisible){krea2PromptReview=null;$("krea2-prompt-review").hidden=true;}else $("krea2-prompt-review").hidden=false;$("krea2-generate").disabled=true;$("krea2-prompt-skip-once").disabled=true;$("krea2-cancel").hidden=false;$("krea2-job-detail").textContent="GPU-, RAM- en modelcontroles uitvoeren… "+(promptSource==="original"?"Originele prompt.":edited?"Handmatig aangepaste prompt.":"Verbeterde prompt.");setKrea2JobState("Controleren…",true);$("krea2-result").hidden=true;$("krea2-result-placeholder").hidden=false;$("krea2-result-actions").hidden=true;$("krea2-prompt-attribution").hidden=false;$("krea2-prompt-attribution").classList.toggle("is-warning",!!(meta?.fallback||warning));$("krea2-prompt-attribution").textContent=promptAttributionText(meta,mode,edited);
 try{const started=await post("/api/krea2/generate",{prompt,promptProvider:meta?.provider||"original",promptModel:meta?.model||null,promptFallback:meta?.fallback===true,promptMode:mode,promptSource,promptEdited:edited,promptWarning:warning,model:$("krea2-model")?.value||undefined,width:Number($("krea2-resolution").value),height:Number($("krea2-resolution").value),seed:Number($("krea2-seed").value),steps:Number($("krea2-steps").value),turboSteps:Number($("krea2-turbo-mode").value)||0,encoder:$("krea2-encoder")?.value||"q4"});krea2ActiveJob=started.job.id;pollKrea2Job(krea2ActiveJob);}catch(e){$("krea2-generate").disabled=false;$("krea2-prompt-skip-once").disabled=false;$("krea2-cancel").hidden=true;setKrea2JobState("Niet gestart");$("krea2-job-detail").textContent=e.message;toast(e.message);}
}
