$("video-enhance-run").addEventListener("click",async()=>{if(!activeVideoSource)return toast("Selecteer eerst een bronvideo.");if(videoJobId)return toast("Er wordt al een video verwerkt.");const payload={sourceId:activeVideoSource.id,upscaleEngine:$("video-enhance-ai-upscale").value,resolution:$("video-enhance-resolution").value,denoise:Number($("video-enhance-denoise").value),sharpen:Number($("video-enhance-sharpen").value),brightness:Number($("video-enhance-brightness").value),contrast:Number($("video-enhance-contrast").value),saturation:Number($("video-enhance-saturation").value),gamma:Number($("video-enhance-gamma").value),stabilize:$("video-enhance-stabilize").checked,deinterlace:$("video-enhance-deinterlace").checked,interpolationEngine:$("video-enhance-interpolation").value,interpolate:$("video-enhance-interpolation").value!=="none",targetFps:Number($("video-enhance-fps").value),preserveAudio:$("video-enhance-audio").checked,quality:Number($("video-enhance-quality").value),trimStart:Number($("video-enhance-trim-start").value),trimEnd:Number($("video-enhance-trim-end").value),speed:Number($("video-enhance-speed").value),rotation:Number($("video-enhance-rotation").value),volume:Number($("video-enhance-volume").value)};$("video-enhance-run").disabled=true;$("video-enhance-cancel").hidden=false;$("video-enhance-progress").hidden=false;$("video-enhance-progress").value=0;$("video-enhance-status").textContent="Videoanalyse en lokale verwerking starten…";try{const d=await post("/api/video/enhance",payload);videoJobId=d.job.id;await pollVideoJob();if(videoJobId)videoPollTimer=setInterval(pollVideoJob,1200);}catch(err){$("video-enhance-status").textContent="Starten mislukt: "+err.message;$("video-enhance-run").disabled=!activeVideoSource;$("video-enhance-cancel").hidden=true;$("video-enhance-progress").hidden=true;toast(err.message);}});
$("video-enhance-cancel").addEventListener("click",async()=>{try{await post("/api/video/cancel",{});$("video-enhance-status").textContent="Stopverzoek verzonden…";}catch(e){toast(e.message);}});
$("video-library-search").addEventListener("input",renderVideoLibrary);$("video-library-filter").addEventListener("change",renderVideoLibrary);$("video-library-sort").addEventListener("change",renderVideoLibrary);$("video-refresh-library").addEventListener("click",loadVideoLibrary);
$("video-source").addEventListener("change",async e=>{const f=e.target.files?.[0];videoSourceData=null;$("video-source-preview-wrap").hidden=true;if(!f)return;if(!/^image\/(png|jpeg|webp)$/.test(f.type)||f.size>16*1024*1024){toast("Kies een PNG-, JPEG- of WebP-afbeelding van maximaal 16 MB");e.target.value="";return;}try{videoSourceData=await readData(f);$("video-source-preview").src=videoSourceData;$("video-source-name").textContent=f.name+" · "+fmtBytes(f.size);$("video-source-preview-wrap").hidden=false;}catch(err){toast(err.message);}});
$("video-source-remove").addEventListener("click",()=>{videoSourceData=null;$("video-source").value="";$("video-source-preview-wrap").hidden=true;});
function showVideoResult(job){if(job.engine==="ffmpeg"){if(job.state==="completed"&&job.videos?.length){const v=job.videos[0];$("video-enhance-after").src=v.url;$("video-enhance-after").load();$("video-enhance-download").href=v.url;$("video-enhance-download").download=v.name;$("video-enhance-download").hidden=false;$("video-enhance-after-info").textContent=job.outputMetadata?job.outputMetadata.width+" × "+job.outputMetadata.height+" · "+formatVideoTime(job.outputMetadata.duration)+" · "+(job.outputMetadata.fps?job.outputMetadata.fps.toFixed(2)+" fps":"fps onbekend"):v.name;$("video-enhance-result-info").textContent=(job.upscaling?"AI-upscaling met "+job.upscaling:"Verwerkt met "+(job.interpolation||"FFmpeg CPU"))+" · "+(job.filters||[]).join(" · ")+". De bronvideo is ongewijzigd bewaard.";$("video-enhance-status").textContent="Video verbeterd en opgeslagen.";$("video-enhance-progress").value=100;$("video-enhance-progress").hidden=false;}else if(job.state==="error"){$("video-enhance-status").textContent="Verwerking mislukt: "+(job.error||"Onbekende fout");$("video-enhance-progress").hidden=true;}else if(job.state==="cancelled"){$("video-enhance-status").textContent="Videobewerking gestopt.";$("video-enhance-progress").hidden=true;}else{$("video-enhance-status").textContent=job.stage||"Video wordt lokaal verwerkt…";$("video-enhance-progress").hidden=false;$("video-enhance-progress").value=job.progress?.percent||0;}return;}if(job.state==="completed"&&job.videos?.length){$("video-result").innerHTML=job.videos.map(v=>"<video class=\"video-player\" controls autoplay muted playsinline src=\""+esc(v.url)+"\"></video><a class=\"primary-button video-download\" href=\""+esc(v.url)+"\" download=\""+esc(v.name)+"\">Video downloaden</a>").join("");$("video-progress").value=100;$("video-status").textContent="Video voltooid en opgeslagen in je videobibliotheek.";}else if(job.state==="error"){$("video-status").textContent="Generatie mislukt: "+(job.error||"Onbekende fout");$("video-progress").hidden=true;}else if(job.state==="cancelled"){$("video-status").textContent="Video-generatie gestopt.";$("video-progress").hidden=true;}else{$("video-status").textContent=job.state==="running"?"Video wordt gegenereerd op de native Vulkan-GPU · segment "+(job.progress?.segment||job.segment||1)+"/"+(job.progress?.totalSegments||job.segmentCount||1)+"…":"Video staat in de native GPU-wachtrij…";$("video-progress").hidden=false;}}
async function prepareNativeVideoImage(data,width,height){return await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>{const canvas=document.createElement("canvas");canvas.width=width;canvas.height=height;const ctx=canvas.getContext("2d");const scale=Math.max(width/img.width,height/img.height),w=img.width*scale,h=img.height*scale;ctx.drawImage(img,(width-w)/2,(height-h)/2,w,h);resolve(canvas.toDataURL("image/jpeg",.92));};img.onerror=()=>reject(Error("Startafbeelding kon niet worden voorbereid"));img.src=data;});}
async function pollVideoJob(){if(!videoJobId)return;try{const d=await api("/api/video/jobs/"+encodeURIComponent(videoJobId)),job=d.job;showVideoResult(job);if(job.progress?.total_steps)$("video-progress").value=Math.round(100*(job.progress.step||0)/job.progress.total_steps);if(job.engine==="ffmpeg"&&job.progress?.percent!=null)$("video-enhance-progress").value=job.progress.percent;if(["completed","error","cancelled"].includes(job.state)){clearInterval(videoPollTimer);videoPollTimer=null;videoJobId=null;$("video-generate").disabled=!nativeVideoRuntimeReady;$("video-enhance-run").disabled=!activeVideoSource;$("video-cancel").hidden=true;$("video-enhance-cancel").hidden=true;if(job.state==="completed")await loadVideoLibrary();}}catch(e){$("video-status").textContent="Status ophalen mislukt: "+e.message;}}
$("video-generate").addEventListener("click",async()=>{if(!nativeVideoRuntimeReady)return toast("Laad eerst een passend videomodel in de native Vulkan-engine");if(videoMode==="image"&&!videoSourceData)return toast("Kies eerst een startafbeelding");const prompt=$("video-prompt").value.trim();if(!prompt)return toast("Vul eerst een videoprompt in");const [w,h]=$("video-resolution").value.split("x").map(Number),fps=Number($("video-fps").value)||12,duration=Math.max(1,Math.min(60,Number($("video-duration").value)||4));let frames=Math.max(9,Math.min(289,Math.round(duration*fps)));frames=Math.max(5,Math.min(81,Math.round((frames-1)/4)*4+1));$("video-generate").disabled=true;$("video-cancel").hidden=false;$("video-progress").hidden=false;$("video-progress").removeAttribute("value");$("video-status").textContent="Native Vulkan-videogeneratie voorbereiden…";$("video-result").innerHTML="<div class=\"empty-state\">Video wordt voorbereid…</div>";try{const payload={mode:videoMode,duration,prompt,negative:$("video-negative").value,image:videoMode==="image"?await prepareNativeVideoImage(videoSourceData,w,h):null,width:w,height:h,fps,frames,steps:Number($("video-steps").value)||20,cfg:Number($("video-cfg").value)||6,flowShift:Number($("video-flow-shift").value)||3,seed:Number($("video-seed").value)};const d=await post("/api/video/native/generate",payload);videoJobId=d.job.id;await pollVideoJob();if(videoJobId)videoPollTimer=setInterval(pollVideoJob,2500);}catch(e){$("video-status").textContent="Starten mislukt: "+e.message;$("video-progress").hidden=true;$("video-cancel").hidden=true;$("video-generate").disabled=!nativeVideoRuntimeReady;toast(e.message);}});
$("video-cancel").addEventListener("click",async()=>{try{await post("/api/video/cancel",{});if(videoPollTimer)clearInterval(videoPollTimer);videoPollTimer=null;videoJobId=null;$("video-cancel").hidden=true;$("video-generate").disabled=!nativeVideoRuntimeReady;$("video-status").textContent="Stopverzoek verzonden naar de native GPU-engine.";$("video-progress").hidden=true;}catch(e){toast(e.message);}});
